using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 changed the discriminator property from "Discriminator" to "$type".
            // Preserve "Discriminator" so existing 500K documents remain readable and
            // direct SQL queries referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the id format from "EntityType|KeyValue" to just "KeyValue".
            // Preserve the "EntityType|" prefix so existing documents stay accessible.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id");
            entity.UseETagConcurrency();
        });

        // HasIndex is not supported by the Cosmos provider — removed.
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Keep the EF Core 8 id format "Product|123" for backward compatibility.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Metadata.Conventions.CosmosNoIdWithDiscriminatorConvention());
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

